// The app icon is generated at build time from an embedded PNG because the
// GitHub push tooling used for this repo only carries UTF-8 text files,
// so a binary icon cannot be committed directly. The file is only
// rewritten when its bytes differ, so builds stay incremental.
use std::path::PathBuf;

const ICON_PNG_BASE64: &str = "";

fn ensure_icon() {
    let png = base64::Engine::decode(&base64::engine::general_purpose::STANDARD, ICON_PNG_BASE64)
        .expect("embedded icon is valid base64");
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("icons/icon.png");
    write_if_changed(&path, &png);

    // Windows builds need an .ico (tauri-build embeds it as a resource). An ICO
    // can wrap a PNG directly: a 6-byte header, one 16-byte entry, then the PNG.
    // Width/height 0 means 256, the maximum the format can express.
    let mut ico = vec![0, 0, 1, 0, 1, 0, 0, 0, 0, 0, 1, 0, 32, 0];
    ico.extend_from_slice(&(png.len() as u32).to_le_bytes());
    ico.extend_from_slice(&22u32.to_le_bytes());
    ico.extend_from_slice(&png);
    write_if_changed(&path.with_file_name("icon.ico"), &ico);
}

fn write_if_changed(path: &std::path::Path, bytes: &[u8]) {
    let needs_write = std::fs::read(path).map(|b| b != bytes).unwrap_or(true);
    if needs_write {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).expect("create icons dir");
        }
        std::fs::write(path, bytes).expect("write app icon");
    }
}

/// The commit the app is built from, for About and the diagnostics (#208):
/// `NAUVI_COMMIT` if set, else git's, else CI's `GITHUB_SHA`, else
/// "unknown" (a source tarball).
fn set_commit() {
    println!("cargo:rerun-if-env-changed=NAUVI_COMMIT");
    println!("cargo:rerun-if-env-changed=GITHUB_SHA");
    let git = |args: &[&str]| {
        std::process::Command::new("git")
            .args(args)
            .current_dir(env!("CARGO_MANIFEST_DIR"))
            .output()
            .ok()
            .filter(|o| o.status.success())
            .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())
            .filter(|s| !s.is_empty())
    };
    // A commit or checkout rewrites HEAD or appends to its reflog.
    if let Some(dir) = git(&["rev-parse", "--absolute-git-dir"]) {
        for file in ["HEAD", "logs/HEAD"] {
            let path = PathBuf::from(&dir).join(file);
            if path.exists() {
                println!("cargo:rerun-if-changed={}", path.display());
            }
        }
    }
    let commit = std::env::var("NAUVI_COMMIT")
        .ok()
        .filter(|s| !s.is_empty())
        .or_else(|| git(&["rev-parse", "--short=12", "HEAD"]))
        .or_else(|| {
            std::env::var("GITHUB_SHA")
                .ok()
                .map(|s| s.chars().take(12).collect())
        })
        .unwrap_or_else(|| "unknown".into());
    // Only a commit id: nothing else reaches the binary.
    let commit: String = commit
        .chars()
        .filter(|c| c.is_ascii_alphanumeric())
        .take(40)
        .collect();
    let commit = if commit.is_empty() {
        "unknown".into()
    } else {
        commit
    };
    println!("cargo:rustc-env=NAUVI_COMMIT={commit}");
}

fn main() {
    ensure_icon();
    set_commit();
    tauri_build::build()
}
